import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Writing Guides","description":"","frontmatter":{"title":"Writing Guides"},"headers":[],"relativePath":"guides/contributing/writing-documentation/writing-guides.md","filePath":"guides/contributing/writing-documentation/writing-guides.md"}`),a={name:`guides/contributing/writing-documentation/writing-guides.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="writing-effective-guides" tabindex="-1">Writing Effective Guides <a class="header-anchor" href="#writing-effective-guides" aria-label="Permalink to “Writing Effective Guides”">​</a></h1><h2 id="_1-know-your-audience" tabindex="-1">1. Know Your Audience <a class="header-anchor" href="#_1-know-your-audience" aria-label="Permalink to “1. Know Your Audience”">​</a></h2><p><strong><em>Warp</em>Drive</strong>&#39;s Documentation has to balance appealing to many different audiences. Here are some example audiences:</p><ul><li><ol><li>VPs and Directors who hear about <strong><em>Warp</em>Drive</strong> at a conference and feel their team should evaluate whether it solves their business problems</li></ol></li><li><ol start="2"><li>Tech Leads and Senior ICs or Architects who hear about it and want to decide if it solves their tech needs</li></ol></li><li><ol start="3"><li>Hobbyists who heard about it and want to try it for a weekend project</li></ol></li><li><ol start="4"><li>Engineers who just started at a company and want to learn about this thing the company uses</li></ol></li><li><ol start="5"><li>Existing Users who want to find the documentation for something, learn the project deeper, or need to know how to update from X to Y.</li></ol></li></ul><p>Our guides attempt to cater to these varied audiences by defaulting to the assumption that the reader is one that either does not use <strong><em>Warp</em>Drive</strong> yet or is just getting started.</p><p>From this perspective, here are a few guidelines to keep in mind:</p><ul><li>Landing page / introduction content should attempt to entice decision makers (categories 1-3 above)</li><li>Guides material should always start from the assumption that the readers don&#39;t have context on the project&#39;s history (categories 1-4)</li><li>Concepts should always be cross-linked when possible, especially when first introducing the concept (everyone)</li><li>Migrations guides can presume some historical knowledge of older concepts, but should not presume knowledge of newer concepts (categories 4 and 5)</li><li>Guides material specific to legacy should be kept separate from other guides material (categories 4 and 5)</li></ul><p>Some examples of ways to achieve this balance:</p><ul><li><a href="/pr-preview/pr-11154/upgrading/">Upgrading</a> is a top level section to help those category 5 users find what they are looking for faster.</li><li>Explicitly named legacy pages (such as <a href="/pr-preview/pr-11154/guides/configuration/ember">Setup - Legacy (Ember)</a> help those users without muddying instructions for everyone else. Note: this clarity also helps decision makers, as they will like to see that when the time for change comes there are resources to help them that are easy to find and well marked - but which they don&#39;t need to know about just yet.</li></ul><h2 id="_2-iterate-a-lot" tabindex="-1">2. Iterate, A Lot <a class="header-anchor" href="#_2-iterate-a-lot" aria-label="Permalink to “2. Iterate, A Lot”">​</a></h2><p>Making great documentation requires a lot of iteration. A great way to iterate is to write documentation that someone needs, ask them to use it - and use the feedback from where they stumble to improve the documentation for the next person. The more iteration that happens, the more the docs become a source of information that works well for everyone.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};